function snakesAndLadders(board: number[][]): number {
  const n = board.length;
  const target = n * n;

  // Номер клетки (1..n²) -> значение board в этой клетке
  const cellValue = (label: number): number => {
    const rowFromBottom = Math.floor((label - 1) / n);
    const row = n - 1 - rowFromBottom;
    let col = (label - 1) % n;
    // В нечётных (считая снизу с нуля) строках нумерация идёт справа налево
    if (rowFromBottom % 2 === 1) col = n - 1 - col;
    return board[row][col];
  };

  // BFS по номерам клеток: слой = число сделанных бросков
  const visited = new Array<boolean>(target + 1).fill(false);
  visited[1] = true;
  let layer = [1];
  let moves = 0;

  while (layer.length) {
    const next: number[] = [];
    for (const curr of layer) {
      if (curr === target) return moves;
      // Перебираем все 6 исходов броска
      for (let step = 1; step <= 6 && curr + step <= target; step++) {
        let dest = curr + step;
        const jump = cellValue(dest);
        // Змея или лестница переносит нас сразу (только один раз за ход)
        if (jump !== -1) dest = jump;
        if (!visited[dest]) {
          visited[dest] = true;
          next.push(dest);
        }
      }
    }
    layer = next;
    moves++;
  }

  // Последняя клетка недостижима
  return -1;
}

// Время: O(n²) — каждая из n² клеток посещается один раз, у неё не больше 6 переходов
// Память: O(n²) — visited и очередь
